from pathlib import Path
import requests,json,pandas as pd
root=Path.cwd();out=root/'.tmp/s012/independent';p={'fields1':'f1,f2,f3,f4,f5,f6','fields2':'f51,f52,f53,f54,f55,f56,f57,f58,f59,f60,f61','ut':'7eea3edcaed734bea9cbfc24409ed989','klt':'101','fqt':'0','secid':'1.518850','beg':'20200605','end':'20260930','lmt':'10000'}
r=requests.get('https://push2his.eastmoney.com/api/qt/stock/kline/get',params=p,timeout=20);r.raise_for_status();j=r.json();(out/'eastmoney_daily_full_raw.json').write_text(json.dumps(j,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n');v=[x.split(',') for x in j['data']['klines']];em=pd.DataFrame(v,columns=['Date','Open','Close','High','Low','VolumeHand','Amount','Amplitude','ChangePct','Change','Turnover']).set_index('Date');daily=pd.read_parquet(root/'.tmp/s012/dev-intraday/518850.SH_daily.parquet');daily['Date']=pd.to_datetime(daily.Date).dt.strftime('%Y-%m-%d');daily=daily.set_index('Date');bad=json.loads((root/'.tmp/s012/dev-intraday/518850.SH_differences.json').read_text(encoding='utf-8'));dates=[x['day'] for x in bad if 'Volume' not in x['fields']];missing=[d for d in dates if d not in em.index];diff=[]
